//! MAVLink dialect Rust bindings generated by mavlink-bindgen.
//!
//! Enable a dialect by enabling its Cargo feature:
//! - dialect-ardupilotmega
//! - dialect-asluav
//! - dialect-avssuas
//! - dialect-common
//! - dialect-csairlink
//! - dialect-cubepilot
//! - dialect-development
//! - dialect-dynamic
//! - dialect-icarous
//! - dialect-loweheiser
//! - dialect-marsh
//! - dialect-minimal
//! - dialect-paparazzi
//! - dialect-python_array_test
//! - dialect-standard
//! - dialect-stemstudios
//! - dialect-storm32
//! - dialect-test
//! - dialect-ualberta
//! - dialect-uavionix

/// Git SHA of the MAVLink definitions used to generate the bindings, when available.
///
/// This is [`None`] when `git` fails to resolve the commit SHA.
pub const MAVLINK_DEFINITIONS_SHA: Option<&str> = option_env!("MAVLINK_SHA");

include!(concat!(env!("OUT_DIR"), "/mod.rs"));

#[cfg(feature = "dialect-dynamic")]
pub mod dynamic;

#[cfg(feature = "dialect-dynamic")]
mod dynamic_parser;

#[cfg(all(feature = "dialect-dynamic", feature = "serde"))]
mod dynamic_serde;
